from datetime import datetime
now=datetime.now()
print('now:', now, 'year', now.year, 'month', now.month)
profile=apis.supervisor.show_profile()
email=profile['email']
print('profile email:', email)
creds=apis.supervisor.show_account_passwords()
cred_map={c['account_name']: c['password'] for c in creds}
print('cred accounts:', sorted(cred_map.keys()))

apps=['amazon','venmo','spotify']

# login once per app
access_tokens={}
for app in apps:
    login_pwd=cred_map.get(app)
    if not login_pwd:
        print('missing password for', app)
        continue
    res=apis.__getattr__(app).login(username=email, password=login_pwd)
    access_tokens[app]=res.get('access_token')
    print(app,'login token type',res.get('token_type'),'token prefix',access_tokens[app][:10] if access_tokens[app] else None)


def is_expired_card(card):
    y=int(card['expiry_year'])
    m=int(card['expiry_month'])
    return (y, m) < (now.year, now.month)

pre_delete={}
deleted={}
for app in apps:
    token=access_tokens.get(app)
    if not token:
        continue
    cards=apis.__getattr__(app).show_payment_cards(access_token=token)
    pre_delete[app]=cards
    expired=[c for c in cards if is_expired_card(c)]
    deleted[app]=[c['payment_card_id'] for c in expired]
    print(app,'payment_cards total',len(cards),'expired',len(expired))
    if expired:
        print(app,'expired ids',deleted[app])
        print(app,'expired cards',[(c['payment_card_id'],c['card_name'],c['card_number'],c['expiry_year'],c['expiry_month']) for c in expired])

# delete expired
for app in apps:
    token=access_tokens.get(app)
    if not token:
        continue
    for cid in deleted.get(app, []):
        res=apis.__getattr__(app).delete_payment_card(payment_card_id=cid, access_token=token)
        print('deleted',app,'payment_card_id',cid,'->',res)

# verification after deletion
post_delete={}
for app in apps:
    token=access_tokens.get(app)
    if not token:
        continue
    cards=apis.__getattr__(app).show_payment_cards(access_token=token)
    post_delete[app]=cards
    expired=[c for c in cards if is_expired_card(c)]
    print(app,'after delete total',len(cards),'expired remaining',len(expired))
    if expired:
        print(app,'expired remaining ids', [c['payment_card_id'] for c in expired])
        print(app,'expired remaining cards',[(c['payment_card_id'],c['card_name'],c['card_number'],c['expiry_year'],c['expiry_month']) for c in expired])

print('done')
